        }
    }

    private static void CheckAnyRequestCreate(RequestCreate value, InputCheck check, string path)
    {
        switch (value)
        {
            case LeaveRequestCreate derived:
                CheckLeaveRequestCreate(derived, check, path);
                break;
            case PunchCorrectionRequestCreate derived:
                CheckPunchCorrectionRequestCreate(derived, check, path);
                break;
            default:
                CheckRequestCreate(value, check, path);
                break;
        }
    }
}
